Generate one complete Modelica model for this requirement:
Generate a multi-robot system named MarinePairHandoffA. Two 80 kg AUVs each carry surge and heave thrusters, IMU, pressure depth, DVL, and a delayed acoustic modem. Eight bidirectional thruster channels control the pair, with a command magnitude limit of 75.6 N-per-thruster. Divide an inspection task, exchange a timestamped result, and replan one robot using the received data. Preserve each robot's local sensors and record communication send, receive, and data age. Use walls, markers, or survey features in a common world frame. Use task allocation with local motion control and explicit handoff state. Apply a controlled 0.05 s communication delay disturbance during the middle third of the scenario. Run at 80 Hz for 8 s and retain synchronized state, command, and sensor traces. Require actuator and separation bounds, bounded data age, successful handoff, no collision, and task completion, primary tracking error below 0.54 m after 5.2 s, and no NaN or infinite physical, control, or estimator values. Treat facts not stated in this request as unknown rather than inventing them.

The previous model did not compile. Repair it and return one complete model.

Compiler feedback:
Compilation failed.

Previous model:
model MarinePairHandoffA
  parameter Real T = 0.0125 "Sample period (80 Hz, s)";
  parameter Real tend = 8.0 "Scenario duration (s)";
  parameter Real tDelayOn = 8.0/3.0 "Middle third start (s)";
  parameter Real tDelayOff = 16.0/3.0 "Middle third end (s)";
  parameter Real commDelayBase = 0.02 "Nominal modem delay (s)";
  parameter Real commDelayDist = 0.05 "Disturbance delay added in middle third (s)";
  parameter Real commDelayMax = 0.2 "Maximum delay for delay() buffer (s)";

  parameter Real m_auv = 80.0 "AUV mass (kg)";
  parameter Real Iyaw = 8.0 "Yaw inertia (kg m^2)";
  parameter Real dragX = 18.0 "Surge drag (N s/m)";
  parameter Real dragZ = 18.0 "Heave drag (N s/m)";
  parameter Real dragYaw = 6.0 "Yaw drag (N m s)";
  parameter Real armSurge = 0.4 "Thruster moment arm (m)";
  parameter Real Fmax = 75.6 "Per-thruster command limit (N)";

  parameter Real wallXmax = 10.0 "Right wall x (m)";
  parameter Real wallXmin = -1.0 "Left wall x (m)";
  parameter Real zTop = 5.0 "Upper vertical bound (m)";
  parameter Real zBot = -8.0 "Lower vertical bound (m)";
  parameter Real sepMin = 1.2 "Minimum inter-AUV separation (m)";
  parameter Real marker1x = 3.0 "Inspection marker 1 x (m)";
  parameter Real marker1z = 0.5 "Inspection marker 1 z (m)";
  parameter Real marker2x = 6.0 "Inspection marker 2 x (m)";
  parameter Real marker2z = -0.5 "Inspection marker 2 z (m)";
  parameter Real home2x = 0.0 "AUV2 home x (m)";
  parameter Real home2z = -3.0 "AUV2 home z (m)";
  parameter Real tolReach = 0.25 "Reach tolerance (m)";

  parameter Real kpx = 300.0 "Surge position gain";
  parameter Real kdx = 220.0 "Surge damping gain";
  parameter Real kpz = 300.0 "Heave position gain";
  parameter Real kdz = 220.0 "Heave damping gain";
  parameter Real kpyaw = 32.0 "Yaw position gain";
  parameter Real kdyaw = 22.0 "Yaw damping gain";

  Real x1(start=0.0, fixed=true) "AUV1 world x (m)";
  Real z1(start=0.0, fixed=true) "AUV1 world z (m)";
  Real yaw1(start=0.0, fixed=true) "AUV1 heading (rad)";
  Real vx1(start=0.0, fixed=true) "AUV1 surge velocity (m/s)";
  Real vz1(start=0.0, fixed=true) "AUV1 heave velocity (m/s)";
  Real wy1(start=0.0, fixed=true) "AUV1 yaw rate (rad/s)";

  Real x2(start=0.0, fixed=true) "AUV2 world x (m)";
  Real z2(start=-3.0, fixed=true) "AUV2 world z (m)";
  Real yaw2(start=0.0, fixed=true) "AUV2 heading (rad)";
  Real vx2(start=0.0, fixed=true) "AUV2 surge velocity (m/s)";
  Real vz2(start=0.0, fixed=true) "AUV2 heave velocity (m/s)";
  Real wy2(start=0.0, fixed=true) "AUV2 yaw rate (rad/s)";

  discrete Real Fs_l1(start=0.0) "AUV1 surge-left command (N)";
  discrete Real Fs_r1(start=0.0) "AUV1 surge-right command (N)";
  discrete Real Fh_f1(start=0.0) "AUV1 heave-forward command (N)";
  discrete Real Fh_a1(start=0.0) "AUV1 heave-aft command (N)";
  discrete Real Fs_l2(start=0.0) "AUV2 surge-left command (N)";
  discrete Real Fs_r2(start=0.0) "AUV2 surge-right command (N)";
  discrete Real Fh_f2(start=0.0) "AUV2 heave-forward command (N)";
  discrete Real Fh_a2(start=0.0) "AUV2 heave-aft command (N)";

  Real Fs_l1a, Fs_r1a, Fh_f1a, Fh_a1a;
  Real Fs_l2a, Fs_r2a, Fh_f2a, Fh_a2a;
  Real Fx1, Fz1, Myaw1, Fx2, Fz2, Myaw2;

  Real imu_ax1, imu_az1, imu_w1, imu_yaw1;
  Real dvl_vx1, dvl_vz1;
  Real depth1;
  Real imu_ax2, imu_az2, imu_w2, imu_yaw2;
  Real dvl_vx2, dvl_vz2;
  Real depth2;

  Real msg1_x(start=0.0, fixed=true);
  Real msg1_z(start=0.0, fixed=true);
  Real msg1_stamp(start=-1.0, fixed=true);
  Real msg1_done(start=0.0, fixed=true);
  Real msg2_x(start=0.0, fixed=true);
  Real msg2_z(start=0.0, fixed=true);
  Real msg2_stamp(start=-1.0, fixed=true);
  Real msg2_done(start=0.0, fixed=true);

  Real rx2_x_b, rx2_z_b, rx2_stamp_b, rx2_done_b;
  Real rx2_x_d, rx2_z_d, rx2_stamp_d, rx2_done_d;
  Real rx1_x_b, rx1_z_b, rx1_stamp_b, rx1_done_b;
  Real rx1_x_d, rx1_z_d, rx1_stamp_d, rx1_done_d;
  Real rx2_x, rx2_z, rx2_stamp, rx2_done;
  Real rx1_x, rx1_z, rx1_stamp, rx1_done;

  discrete Real send1_t(start=-100.0);
  discrete Real send2_t(start=-100.0);
  discrete Real recv1_t(start=-100.0);
  discrete Real recv2_t(start=-100.0);
  Real ageData1, ageData2;
  Boolean delayActive;

  Integer handoffState(start=0) "Handoff state machine";
  discrete Real target1x(start=marker1x);
  discrete Real target1z(start=marker1z);
  discrete Real target2x(start=home2x);
  discrete Real target2z(start=home2z);
  Boolean task1Done(start=false, fixed=true);
  Boolean task2Done(start=false, fixed=true);
  Boolean replanned2(start=false, fixed=true);
  Boolean taskComplete, handoffOK, noCollision;
  Real sepDist;
  Real trackingErr1, trackingErr2;

  discrete Real err1x, err1z, yawErr1, Fx1_des, Fz1_des, Myaw1_des;
  discrete Real err2x, err2z, yawErr2, Fx2_des, Fz2_des, Myaw2_des;

equation
  der(x1) = vx1;
  der(z1) = vz1;
  der(yaw1) = wy1;
  m_auv*der(vx1) = Fx1 - dragX*vx1;
  m_auv*der(vz1) = Fz1 - dragZ*vz1;
  Iyaw*der(wy1) = Myaw1 - dragYaw*wy1;
  Fx1 = Fs_l1a + Fs_r1a;
  Fz1 = Fh_f1a + Fh_a1a;
  Myaw1 = (Fs_r1a - Fs_l1a)*armSurge;

  der(x2) = vx2;
  der(z2) = vz2;
  der(yaw2) = wy2;
  m_auv*der(vx2) = Fx2 - dragX*vx2;
  m_auv*der(vz2) = Fz2 - dragZ*vz2;
  Iyaw*der(wy2) = Myaw2 - dragYaw*wy2;
  Fx2 = Fs_l2a + Fs_r2a;
  Fz2 = Fh_f2a + Fh_a2a;
  Myaw2 = (Fs_r2a - Fs_l2a)*armSurge;

  Fs_l1a = if Fs_l1 > Fmax then Fmax elseif Fs_l1 < -Fmax then -Fmax else Fs_l1;
  Fs_r1a = if Fs_r1 > Fmax then Fmax elseif Fs_r1 < -Fmax then -Fmax else Fs_r1;
  Fh_f1a = if Fh_f1 > Fmax then Fmax elseif Fh_f1 < -Fmax then -Fmax else Fh_f1;
  Fh_a1a = if Fh_a1 > Fmax then Fmax elseif Fh_a1 < -Fmax then -Fmax else Fh_a1;
  Fs_l2a = if Fs_l2 > Fmax then Fmax elseif Fs_l2 < -Fmax then -Fmax else Fs_l2;
  Fs_r2a = if Fs_r2 > Fmax then Fmax elseif Fs_r2 < -Fmax then -Fmax else Fs_r2;
  Fh_f2a = if Fh_f2 > Fmax then Fmax elseif Fh_f2 < -Fmax then -Fmax else Fh_f2;
  Fh_a2a = if Fh_a2 > Fmax then Fmax elseif Fh_a2 < -Fmax then -Fmax else Fh_a2;

  imu_ax1 = der(vx1);
  imu_az1 = der(vz1);
  imu_w1 = wy1;
  imu_yaw1 = yaw1;
  dvl_vx1 = vx1;
  dvl_vz1 = vz1;
  depth1 = z1;

  imu_ax2 = der(vx2);
  imu_az2 = der(vz2);
  imu_w2 = wy2;
  imu_yaw2 = yaw2;
  dvl_vx2 = vx2;
  dvl_vz2 = vz2;
  depth2 = z2;

  der(msg1_x) = 0;
  der(msg1_z) = 0;
  der(msg1_stamp) = 0;
  der(msg1_done) = 0;
  der(msg2_x) = 0;
  der(msg2_z) = 0;
  der(msg2_stamp) = 0;
  der(msg2_done) = 0;

  delayActive = (time >= tDelayOn) and (time < tDelayOff);

  rx2_x_b = delay(msg1_x, commDelayBase, commDelayMax);
  rx2_z_b = delay(msg1_z, commDelayBase, commDelayMax);
  rx2_stamp_b = delay(msg1_stamp, commDelayBase, commDelayMax);
  rx2_done_b = delay(msg1_done, commDelayBase, commDelayMax);
  rx2_x_d = delay(msg1_x, commDelayBase + commDelayDist, commDelayMax);
  rx2_z_d = delay(msg1_z, commDelayBase + commDelayDist, commDelayMax);
  rx2_stamp_d = delay(msg1_stamp, commDelayBase + commDelayDist, commDelayMax);
  rx2_done_d = delay(msg1_done, commDelayBase + commDelayDist, commDelayMax);

  rx1_x_b = delay(msg2_x, commDelayBase, commDelayMax);
  rx1_z_b = delay(msg2_z, commDelayBase, commDelayMax);
  rx1_stamp_b = delay(msg2_stamp, commDelayBase, commDelayMax);
  rx1_done_b = delay(msg2_done, commDelayBase, commDelayMax);
  rx1_x_d = delay(msg2_x, commDelayBase + commDelayDist, commDelayMax);
  rx1_z_d = delay(msg2_z, commDelayBase + commDelayDist, commDelayMax);
  rx1_stamp_d = delay(msg2_stamp, commDelayBase + commDelayDist, commDelayMax);
  rx1_done_d = delay(msg2_done, commDelayBase + commDelayDist, commDelayMax);

  rx2_x = if delayActive then rx2_x_d else rx2_x_b;
  rx2_z = if delayActive then rx2_z_d else rx2_z_b;
  rx2_stamp = if delayActive then rx2_stamp_d else rx2_stamp_b;
  rx2_done = if delayActive then rx2_done_d else rx2_done_b;
  rx1_x = if delayActive then rx1_x_d else rx1_x_b;
  rx1_z = if delayActive then rx1_z_d else rx1_z_b;
  rx1_stamp = if delayActive then rx1_stamp_d else rx1_stamp_b;
  rx1_done = if delayActive then rx1_done_d else rx1_done_b;

  ageData2 = if rx2_done > 0.5 then time - rx2_stamp else 0.0;
  ageData1 = if rx1_done > 0.5 then time - rx1_stamp else 0.0;

  sepDist = sqrt(max(1e-6, (x1-x2)*(x1-x2) + (z1-z2)*(z1-z2)));
  noCollision = sepDist >= sepMin;
  trackingErr1 = sqrt(max(1e-6, (x1-target1x)*(x1-target1x) + (z1-target1z)*(z1-target1z)));
  trackingErr2 = sqrt(max(1e-6, (x2-target2x)*(x2-target2x) + (z2-target2z)*(z2-target2z)));
  taskComplete = task1Done and task2Done;
  handoffOK = replanned2 and (handoffState >= 2);

  when sample(0, T) then
    if not pre(task1Done) and abs(x1 - marker1x) < tolReach and abs(z1 - marker1z) < tolReach then
      task1Done := true;
      send1_t := time;
      reinit(msg1_x, x1);
      reinit(msg1_z, z1);
      reinit(msg1_stamp, time);
      reinit(msg1_done, 1.0);
      handoffState := 1;
    end if;

    if rx2_done > 0.5 and not pre(replanned2) then
      recv2_t := time;
      target2x := marker2x + (rx2_x - marker1x);
      target2z := marker2z + (rx2_z - marker1z);
      replanned2 := true;
      handoffState := 2;
    end if;

    if pre(replanned2) and not pre(task2Done) and abs(x2 - target2x) < tolReach and abs(z2 - target2z) < tolReach then
      task2Done := true;
      send2_t := time;
      reinit(msg2_x, x2);
      reinit(msg2_z, z2);
      reinit(msg2_stamp, time);
      reinit(msg2_done, 1.0);
      handoffState := 3;
    end if;

    err1x := target1x - x1;
    err1z := target1z - z1;
    yawErr1 := -yaw1;
    Fx1_des := kpx*err1x - kdx*vx1;
    Fz1_des := kpz*err1z - kdz*vz1;
    Myaw1_des := kpyaw*yawErr1 - kdyaw*wy1;
    Fs_l1 := 0.5*(Fx1_des - Myaw1_des/armSurge);
    Fs_r1 := 0.5*(Fx1_des + Myaw1_des/armSurge);
    Fh_f1 := 0.5*Fz1_des;
    Fh_a1 := 0.5*Fz1_des;

    err2x := target2x - x2;
    err2z := target2z - z2;
    yawErr2 := -yaw2;
    Fx2_des := kpx*err2x - kdx*vx2;
    Fz2_des := kpz*err2z - kdz*vz2;
    Myaw2_des := kpyaw*yawErr2 - kdyaw*wy2;
    Fs_l2 := 0.5*(Fx2_des - Myaw2_des/armSurge);
    Fs_r2 := 0.5*(Fx2_des + Myaw2_des/armSurge);
    Fh_f2 := 0.5*Fz2_des;
    Fh_a2 := 0.5*Fz2_des;
  end when;

  annotation(
    experiment(StartTime=0, StopTime=8.0, Tolerance=1e-6, Interval=0.0125),
    Documentation(info="MarinePairHandoffA: two 80 kg AUVs with surge/heave thrusters, local sensors (IMU, depth, DVL), and delayed acoustic modem. Eight bidirectional thruster channels limited to 75.6 N each. Inspection task divided between AUV1 (marker1) and AUV2 (marker2). AUV1 sends a timestamped result upon completion; AUV2 replans its target using the received data and records send, receive, and data age. Controlled 0.05 s delay disturbance applied during the middle third of the 8 s scenario. Sampled at 80 Hz."));
end MarinePairHandoffA;
